class _Tee:
    def __init__(self, term, logf):
        self.term, self.logf = term, logf

    def write(self, s):
        self.term.write(s)
        self.logf.write(_ANSI.sub("", s))

    def flush(self):
        self.term.flush()
        self.logf.flush()


